package it.meapps.spesascan

internal object EmbeddedSupermarketLogos {
    const val CARREFOUR = ""
    const val ESSELUNGA = ""
    const val CONAD = ""
    const val COOP = ""
    const val LIDL = ""
    const val EUROSPIN = ""
    const val MERCATO = ""

    fun forName(name: String): String? = when (name.lowercase()) {
        "carrefour" -> CARREFOUR
        "esselunga" -> ESSELUNGA
        "conad" -> CONAD
        "coop" -> COOP
        "lidl" -> LIDL
        "eurospin" -> EUROSPIN
        "mercatò", "mercato" -> MERCATO
        else -> null
    }
}
